openMedia=function(){
const w=makeWin('media','Media Player - Project walkthroughs','media',`<div class="player screenshot-player curated-player"><div class="gallery-projects">${P.projects.map((p,i)=>`<button data-track="${i}">${esc(p.name)}</button>`).join('')}</div><div class="gallery-heading"><span data-sequence></span><h2 data-heading></h2></div><div class="screen"></div><p class="gallery-caption" data-caption></p><div class="transport"><button data-previous>Previous</button><button data-play>Play walkthrough</button><button data-next>Next</button><span data-counter></span><a data-full target="_blank" rel="noopener noreferrer">Full size</a><a data-site target="_blank" rel="noopener noreferrer">Live website</a></div><div class="gallery-thumbnails" aria-label="Screenshot navigation"></div></div>`,960);
let picture=0,slideshow=false;
function draw(){const p=P.projects[track],slides=p.gallery,s=slides[picture];w.el.querySelector('[data-sequence]').textContent=p.name;w.el.querySelector('[data-heading]').textContent=s.title;w.el.querySelector('[data-caption]').textContent=s.caption;w.el.querySelector('.screen').innerHTML=`<img src="${esc(s.src)}" alt="${esc(s.title)}" decoding="async" loading="eager" fetchpriority="high">`;w.el.querySelector('[data-counter]').textContent=`${picture+1} of ${slides.length}`;w.el.querySelector('[data-full]').href=s.full;w.el.querySelector('[data-site]').href=p.url;w.el.querySelector('[data-play]').textContent=slideshow?'Pause walkthrough':'Play walkthrough';w.el.querySelectorAll('[data-track]').forEach(b=>{b.classList.toggle('active',+b.dataset.track===track);b.setAttribute('aria-pressed',String(+b.dataset.track===track));});const thumbs=w.el.querySelector('.gallery-thumbnails');thumbs.innerHTML=slides.map((s,i)=>`<button data-slide="${i}" class="${i===picture?'selected':''}" aria-label="${esc(s.title)}" aria-pressed="${i===picture}"><img src="${esc(s.thumb)}" alt="" loading="eager" decoding="async"><span>${String(i+1).padStart(2,'0')} ${esc(s.title)}</span></button>`).join('');thumbs.querySelectorAll('[data-slide]').forEach(b=>b.onclick=()=>{picture=+b.dataset.slide;slideshow=false;draw();});const nextImage=new Image();nextImage.src=slides[(picture+1)%slides.length].src;w.el.querySelector('.status').textContent=`${p.name} | ${s.title} | ${picture+1} of ${slides.length}`;}
w.selectTrack=i=>{track=i;picture=0;slideshow=false;draw();};w.el.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>w.selectTrack(+b.dataset.track));w.el.querySelector('[data-next]').onclick=()=>{picture=(picture+1)%P.projects[track].gallery.length;draw();};w.el.querySelector('[data-previous]').onclick=()=>{picture=(picture+P.projects[track].gallery.length-1)%P.projects[track].gallery.length;draw();};w.el.querySelector('[data-play]').onclick=()=>{slideshow=!slideshow;draw();};const timer=setInterval(()=>{if(slideshow&&!w.el.hidden&&!document.hidden){picture=(picture+1)%P.projects[track].gallery.length;draw();}},6500);w.cleanup=()=>clearInterval(timer);draw();};
selectTrack=function(i){windows.get('media')?.selectTrack(i);};


